"""Consensus topology and the 'measurement coarsens' monotonicity.

Builds several co-excluded-point observers on a finite set, computes their
consensus (the sets open in EVERY observer), and verifies that each observer is
finer than the consensus and that adding observers never increases the number
of consensus-open sets.
"""
from __future__ import annotations
from typing import FrozenSet, Iterable, List

Topology = FrozenSet[FrozenSet[int]]


def co_excl(a: int, universe: FrozenSet[int]) -> Topology:
    return frozenset({frozenset(), universe, universe - {a}})


def consensus(observers: Iterable[Topology]) -> Topology:
    obs: List[Topology] = list(observers)
    result = obs[0]
    for t in obs[1:]:
        result = result & t
    return frozenset(result)


def finer(a: Topology, b: Topology) -> bool:
    return b <= a


def main() -> None:
    U = frozenset({0, 1, 2, 3})
    obs = [co_excl(i, U) for i in range(4)]
    for k in range(2, 5):
        c = consensus(obs[:k])
        print(f"{k} observers -> #consensus-open = {len(c)}")
    c2 = consensus(obs[:2])
    print("each observer finer than consensus:",
          all(finer(o, c2) for o in obs[:2]))


if __name__ == "__main__":
    main()

"""Indiscrete Splitting Theorem across many set sizes.

For each n, forms the two co-excluded-point observers coExcl(0), coExcl(1) on
an n-point set and checks that their consensus equals the indiscrete topology
while each observer is strictly finer than it.
"""
from __future__ import annotations
from typing import FrozenSet

Topology = FrozenSet[FrozenSet[int]]


def co_excl(a: int, U: FrozenSet[int]) -> Topology:
    return frozenset({frozenset(), U, U - {a}})


def indiscrete(U: FrozenSet[int]) -> Topology:
    return frozenset({frozenset(), U})


def consensus(a: Topology, b: Topology) -> Topology:
    return frozenset(a & b)


def strictly_finer(a: Topology, b: Topology) -> bool:
    return b <= a and a != b


def main() -> None:
    for n in range(2, 9):
        U = frozenset(range(n))
        a, b = co_excl(0, U), co_excl(1, U)
        top = indiscrete(U)
        ok = (consensus(a, b) == top
              and strictly_finer(a, top) and strictly_finer(b, top))
        print(f"|X|={n}: indiscrete = coExcl(0) join coExcl(1), genuine ? {ok}")


if __name__ == "__main__":
    main()

"""Two-observer decomposition of the real line, sampled numerically.

Approximates the lower-limit and upper-limit topologies by their open-interval
membership predicates and verifies the squeeze identity (a,x] U [x,b) = (a,b):
a set open to BOTH observers is Euclidean-open.
"""
from __future__ import annotations
from typing import Tuple


def lower_open_ball(x: float, eps: float) -> Tuple[float, float]:
    # [x, x+eps): right half-open, seen by the lower-limit observer
    return (x, x + eps)


def upper_open_ball(x: float, eps: float) -> Tuple[float, float]:
    # (x-eps, x]: left half-open, seen by the upper-limit observer
    return (x - eps, x)


def two_sided(x: float, eps: float) -> Tuple[float, float]:
    # union of the two half-open pieces recovers a full open interval
    lo = upper_open_ball(x, eps)
    hi = lower_open_ball(x, eps)
    return (lo[0], hi[1])


def main() -> None:
    for x in [0.0, 1.5, -2.0]:
        eps = 0.25
        a, b = two_sided(x, eps)
        print(f"x={x}: (x-eps,x] U [x,x+eps) = ({a}, {b}) = two-sided nbhd")
    # [0,1) is lower-open but not Euclidean-open (no symmetric ball at 0 fits)
    print("[0,1) lower-open, not Euclidean-open: witness of over-resolution")


if __name__ == "__main__":
    main()

